#include <stddef.h>
void *malloc(size_t);
void free(void*);
int printf(const char*,...);
int puts(const char*);
int main(void){
  char *a = malloc(0x18);
  unsigned long *top = (unsigned long*)(a + 0x10);
  printf("a=%p\n", (void*)a);
  printf("top_size=0x%lx\n", top[1]);
  puts("write 0xdeadbeef to top->size ...");
  top[1] = 0xdeadbeef;
  printf("after_write top_size=0x%lx\n", top[1]);
  char *b = malloc(0x100);
  printf("b=%p\n", (void*)b);
  return 0;
}
